"""Compare what is still local with the pre-cleanup backup. Prints counts only, never paths or contents."""
import csv
import hashlib
import os
import subprocess
from collections import Counter

REPO = "~/leveraged-etf-risk-analytics"
BACKUP = "~/etf-risk-backups/2026-10-27_pre-cleanup"
SRC = {
    "recovery-outline": os.path.join(REPO, ".claude/worktrees/recovery-outline"),
    "worker-pipeline": os.path.join(REPO, ".claude/worktrees/worker-pipeline"),
    "main-checkout": REPO,
}


def sha(path):
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for chunk in iter(lambda: fh.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def lines(cwd, *args):
    out = subprocess.run(["git", "-C", cwd, "-c", "core.quotePath=false", *args],
                         capture_output=True, text=True, check=True).stdout
    return [line for line in out.splitlines() if line]


backed = {}
with open(os.path.join(BACKUP, "MANIFEST.tsv")) as fh:
    for row in csv.DictReader(fh, delimiter="\t"):
        backed[(row["label"], row["path"])] = row["sha256"]

for label, src in SRC.items():
    # The same three kinds the backup took: untracked, tracked changes, ignored raw originals and config.
    now = set(lines(src, "ls-files", "--others", "--exclude-standard"))
    now |= set(lines(src, "diff", "--name-only", "HEAD"))
    now |= {p for p in lines(src, "ls-files", "--others", "--ignored", "--exclude-standard", "--", "docs/ai-usage", ".claude")
            if p.endswith("/transcript.raw.jsonl") or p == ".claude/transcript-privacy.local.json"}
    c = Counter()
    for (lab, p), digest in backed.items():
        if lab != label:
            continue
        full = os.path.join(src, p)
        if not os.path.isfile(full):
            c["backed up, now missing"] += 1
        elif sha(full) == digest:
            c["same as backup"] += 1
        else:
            c["changed since backup"] += 1
    c["new since backup"] = len({p for p in now if (label, p) not in backed})
    print(f"{label}: " + ", ".join(f"{k} {c[k]}" for k in
          ("same as backup", "changed since backup", "new since backup", "backed up, now missing")))

